content:
msInitExpression(&(label->exprBindings[i]));
  }

  msInitExpression(&(label->expression));
  msInitExpression(&(label->text));

  label->leader = NULL;

  label->sizeunits = MS_INHERIT;
  label->scalefactor = 1.0;

  return;
}

int freeLabelLeader(labelLeaderObj *leader)
{
